{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    edges = []
    for a, b, d in distances:
        left, right = (a, b) if a < b else (b, a)
        w = max(core[left], core[right], d)
        edges.append((w, left, right))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    target = len(nodes) - 1
    for w, left, right in edges:
        if union(left, right):
            mst_edges.append([left, right, w])
            total_weight += w
            if len(mst_edges) == target:
                break
    if len(mst_edges) != target:
        raise ValueError("Disconnected graph")
    return {"mst_edges": mst_edges, "total_weight": total_weight}"}
